SELECT id, task_id, shop_id, conversation_id, open_user_id, shard_no,
       outbound_message_id, status, error_code, error_summary, sent_at,
       create_time, update_time
FROM mt_im_broadcast_record
WHERE task_id = #{taskId}
  AND shard_no = #{shardNo}
  AND status <> 'SENT'
ORDER BY id
LIMIT #{limit}

SELECT COUNT(*) FROM mt_im_broadcast_record
WHERE task_id = #{taskId}
AND status = #{status}
